// ckir_mlp_bench.cu — proof that the CKIR-AUTHORED fused MLP reproduces the crush. The forward kernel is GENERATED by CKIR
// (ckir_mlp_fwd_gen.cu, tool test [.emit-cuda-mlp]) — NOT hand-written here — and duels the same cublasLt pipeline the gold
// ref used, in one binary, correctness-gated. Expect the same ~2.37× as mlp_fused_bench.cu (the hand-written gold).
// Build: nvcc -O3 -std=c++17 -arch=sm_89 -allow-unsupported-compiler -Xcompiler /Zc:preprocessor
//        ckir_mlp_bench.cu -o ckir_mlp_bench.exe -lcublasLt -lcublas
#include "ckir_mlp_fwd_gen.cu" // the CKIR-emitted kernel: ckir_fused_mlp_fwd(in, w, out, nrows)

#include <cublasLt.h>

#include <chrono>
#include <cstdio>
#include <cstdlib>

static void check(cudaError_t e, const char* w)
{
    if (e != cudaSuccess) { std::printf("CUDA ERR %s: %s\n", w, cudaGetErrorString(e)); std::exit(1); }
}
static void checkLt(cublasStatus_t e, const char* w)
{
    if (e != CUBLAS_STATUS_SUCCESS) { std::printf("cublasLt ERR %s: %d\n", w, static_cast<int>(e)); std::exit(1); }
}

constexpr int W_DIM  = 64;
constexpr int LAYERS = 6;
constexpr int BATCH  = 1 << 20;
constexpr int TILE   = 128;

int main()
{
    cudaDeviceProp prop{};
    cudaGetDeviceProperties(&prop, 0);
    std::printf("# CKIR-AUTHORED fused MLP (generated wmma) vs cublasLt — %s\n", prop.name);
    std::printf("# MLP 64 x %d layers, batch %d\n", LAYERS, BATCH);

    __half*  h_in = static_cast<__half*>(malloc(sizeof(__half) * BATCH * W_DIM));
    __half*  h_w  = static_cast<__half*>(malloc(sizeof(__half) * LAYERS * W_DIM * W_DIM));
    unsigned s    = 12345U;
    auto     rnd  = [&]() { s = s * 1664525U + 1013904223U; return static_cast<float>(static_cast<int>(s >> 9) - (1 << 22)) / static_cast<float>(1 << 22); };
    for (int i = 0; i < BATCH * W_DIM; ++i) { h_in[i] = __float2half(rnd()); }
    for (int i = 0; i < LAYERS * W_DIM * W_DIM; ++i) { h_w[i] = __float2half(rnd() * 0.17F); }

    __half *d_in = nullptr, *d_w = nullptr, *d_out = nullptr, *d_a = nullptr, *d_b = nullptr;
    check(cudaMalloc(&d_in, sizeof(__half) * BATCH * W_DIM), "in");
    check(cudaMalloc(&d_w, sizeof(__half) * LAYERS * W_DIM * W_DIM), "w");
    check(cudaMalloc(&d_out, sizeof(__half) * BATCH * W_DIM), "out");
    check(cudaMalloc(&d_a, sizeof(__half) * BATCH * W_DIM), "acta");
    check(cudaMalloc(&d_b, sizeof(__half) * BATCH * W_DIM), "actb");
    check(cudaMemcpy(d_in, h_in, sizeof(__half) * BATCH * W_DIM, cudaMemcpyHostToDevice), "up in");
    check(cudaMemcpy(d_w, h_w, sizeof(__half) * LAYERS * W_DIM * W_DIM, cudaMemcpyHostToDevice), "up w");

    cublasLtHandle_t lt;
    checkLt(cublasLtCreate(&lt), "create");
    cublasLtMatmulDesc_t opRelu, opLin;
    checkLt(cublasLtMatmulDescCreate(&opRelu, CUBLAS_COMPUTE_16F, CUDA_R_16F), "desc");
    checkLt(cublasLtMatmulDescCreate(&opLin, CUBLAS_COMPUTE_16F, CUDA_R_16F), "desc2");
    cublasLtEpilogue_t epi = CUBLASLT_EPILOGUE_RELU;
    checkLt(cublasLtMatmulDescSetAttribute(opRelu, CUBLASLT_MATMUL_DESC_EPILOGUE, &epi, sizeof(epi)), "epi");
    cublasLtMatrixLayout_t lw, la, lc;
    checkLt(cublasLtMatrixLayoutCreate(&lw, CUDA_R_16F, W_DIM, W_DIM, W_DIM), "lw");
    checkLt(cublasLtMatrixLayoutCreate(&la, CUDA_R_16F, W_DIM, BATCH, W_DIM), "la");
    checkLt(cublasLtMatrixLayoutCreate(&lc, CUDA_R_16F, W_DIM, BATCH, W_DIM), "lc");
    const __half one  = __float2half(1.0F);
    const __half zero = __float2half(0.0F);
    const auto   cublas_mlp = [&]() {
        const __half* src = d_in;
        __half*       pa  = d_a;
        __half*       pb  = d_b;
        for (int l = 0; l < LAYERS; ++l)
        {
            const __half* wl  = d_w + static_cast<size_t>(l) * W_DIM * W_DIM;
            __half*       dst = (l + 1 == LAYERS) ? d_out : pa;
            checkLt(cublasLtMatmul(lt, (l + 1 == LAYERS) ? opLin : opRelu, &one, wl, lw, src, la, &zero, dst, lc, dst, lc,
                                   nullptr, nullptr, 0, nullptr),
                    "matmul");
            src       = dst;
            __half* t = pa;
            pa        = pb;
            pb        = t;
        }
    };
    const auto ckir = [&]() { ckir_fused_mlp_fwd<<<BATCH / TILE, 64>>>(d_in, d_w, d_out, BATCH); };

    // correctness: CKIR-emitted kernel vs cuBLAS (same fp16 math, deterministic schedule)
    __half* h_ref = static_cast<__half*>(malloc(sizeof(__half) * BATCH * W_DIM));
    __half* h_got = static_cast<__half*>(malloc(sizeof(__half) * BATCH * W_DIM));
    cublas_mlp();
    check(cudaDeviceSynchronize(), "cublas");
    check(cudaMemcpy(h_ref, d_out, sizeof(__half) * BATCH * W_DIM, cudaMemcpyDeviceToHost), "ref");
    ckir();
    check(cudaDeviceSynchronize(), "ckir");
    check(cudaMemcpy(h_got, d_out, sizeof(__half) * BATCH * W_DIM, cudaMemcpyDeviceToHost), "got");
    {
        double maxad = 0.0, maxmag = 0.0;
        for (int i = 0; i < BATCH * W_DIM; ++i)
        {
            const double r = __half2float(h_ref[i]);
            const double g = __half2float(h_got[i]);
            const double d = r > g ? r - g : g - r;
            if (d > maxad) { maxad = d; }
            const double m = r < 0 ? -r : r;
            if (m > maxmag) { maxmag = m; }
        }
        std::printf("# correctness (CKIR vs cuBLAS): max_abs_diff=%.5f max_ref_mag=%.5f rel=%.5f\n", maxad, maxmag, maxad / (maxmag > 0 ? maxmag : 1));
        if (maxmag < 1e-3 || maxad / maxmag > 0.08) { std::printf("# MISMATCH\n"); return 2; }
    }

    // WEIGHT-CONVENTION PROBE: compute the host reference with BOTH layouts, report which matches the CKIR kernel.
    // conv A: out[n] = sum_k a[k]*w[k + W*n]  (column-major B)   conv B: out[n] = sum_k a[k]*w[k*W + n] (row-major B)
    {
        float* a0 = static_cast<float*>(malloc(sizeof(float) * W_DIM));
        float* a1 = static_cast<float*>(malloc(sizeof(float) * W_DIM));
        double relA = 0.0, relB = 0.0;
        for (int r = 0; r < 64; ++r) // a small sample of rows
        {
            for (int conv = 0; conv < 2; ++conv)
            {
                for (int c = 0; c < W_DIM; ++c) { a0[c] = __half2float(h_in[r * W_DIM + c]); }
                float* cur = a0;
                float* nxt = a1;
                for (int l = 0; l < LAYERS; ++l)
                {
                    for (int n = 0; n < W_DIM; ++n)
                    {
                        float acc = 0.0F;
                        for (int k = 0; k < W_DIM; ++k)
                        {
                            const float wv = __half2float(h_w[l * W_DIM * W_DIM + (conv == 0 ? (k + W_DIM * n) : (k * W_DIM + n))]);
                            acc += __half2float(__float2half(cur[k])) * wv; // simulate fp16 activations
                        }
                        nxt[n] = (l + 1 < LAYERS && acc < 0.0F) ? 0.0F : __half2float(__float2half(acc));
                    }
                    float* t = cur; cur = nxt; nxt = t;
                }
                for (int n = 0; n < W_DIM; ++n)
                {
                    const double got = __half2float(h_got[r * W_DIM + n]);
                    const double d   = std::fabs(got - cur[n]) / (std::fabs(cur[n]) + 1e-3);
                    if (conv == 0) { relA = d > relA ? d : relA; }
                    else { relB = d > relB ? d : relB; }
                }
            }
        }
        std::printf("# weight-convention probe: conv A (w[k+W*n]) rel=%.4f | conv B (w[k*W+n]) rel=%.4f -> TRUE = %s\n",
                    relA, relB, relB < relA ? "B (row-major w[k*W+n])" : "A (col-major w[k+W*n])");
        free(a0); free(a1);
    }

    // determinism: run the CKIR kernel twice, must be bit-identical (fixed schedule, no atomics)
    {
        ckir();
        check(cudaDeviceSynchronize(), "ckir det1");
        check(cudaMemcpy(h_ref, d_out, sizeof(__half) * BATCH * W_DIM, cudaMemcpyDeviceToHost), "det rb1");
        ckir();
        check(cudaDeviceSynchronize(), "ckir det2");
        check(cudaMemcpy(h_got, d_out, sizeof(__half) * BATCH * W_DIM, cudaMemcpyDeviceToHost), "det rb2");
        int diff = 0;
        for (int i = 0; i < BATCH * W_DIM; ++i) { if (h_ref[i] != h_got[i]) { ++diff; } }
        std::printf("# determinism (run-to-run): %d/%d differing halves %s\n", diff, BATCH * W_DIM, diff == 0 ? "(BIT-IDENTICAL)" : "(NONDETERMINISTIC!)");
        if (diff != 0) { return 3; }
    }

    const auto bench = [&](const char* nm, const auto& fn) {
        for (int wi = 0; wi < 3; ++wi) { fn(); }
        check(cudaDeviceSynchronize(), "warm");
        double best = 1e30;
        for (int r = 0; r < 7; ++r)
        {
            const auto t0 = std::chrono::high_resolution_clock::now();
            for (int it = 0; it < 50; ++it) { fn(); }
            check(cudaDeviceSynchronize(), "sync");
            const auto   t1 = std::chrono::high_resolution_clock::now();
            const double ms = std::chrono::duration<double, std::milli>(t1 - t0).count() / 50.0;
            if (ms < best) { best = ms; }
        }
        const double flops = 2.0 * BATCH * W_DIM * W_DIM * LAYERS;
        std::printf("%-20s %.5f ms   %.1f TFLOP/s (fp16)\n", nm, best, flops / (best * 1.0e9));
        return best;
    };
    const double tc = bench("cublasLt-MLP", cublas_mlp);
    const double tf = bench("CKIR-fused-MLP", ckir);
    std::printf("# RATIO: CKIR-authored fused is %.2fx vs cublasLt\n", tc / tf);
    return 0;
}
